package com.capstone_project.medispot.Databases;import android.content.Context;import android.content.SharedPreferences;import java.util.HashMap;public class SharedUserPreferences {    SharedPreferences sharedPreferences;    SharedPreferences.Editor editor;    Context context;    /*----------------------Session variables------------------------*/    public static final String isLoggedIn = "IsLoggedIn";    public static final String remember = "RememberMe";    public static final String forgot = "IsForgot";    /*----------------------Login variables------------------------*/    public static final String Name = "name";    public static final String Email = "email";    public static final String Phone = "phone";    public static final String DOB = "dob";    public static final String Password = "password";    /*----------------------Remember me variables------------------------*/    private static final String isRemember = "IsRememberMe";    public static final String rememberPhone = "phone";    public static final String rememberPassword = "password";    /*----------------------Forgot Password variables------------------------*/    private static final String isForgotPassword = "IsForgotPass";    public static final String verifyPhone = "phoneOTP";    /*---------------------------------------------------------------------------------------*/    /*---------------------------------------------------------------------------------------*/    public SharedUserPreferences(Context userContext, String sessionName) {        context = userContext;        sharedPreferences = context.getSharedPreferences(sessionName, Context.MODE_PRIVATE);        editor = sharedPreferences.edit();    }    /*----------------------LOGIN------------------------*/    public void createLoggedSession(String name, String email, String dob, String phone, String password) {        editor.putBoolean(isLoggedIn, true);        editor.putString(Name, name);        editor.putString(Email, email);        editor.putString(Phone, phone);        editor.putString(DOB, dob);        editor.putString(Password, password);        editor.commit();    }    public HashMap<String, String> getSessionInfo() {        HashMap<String, String> userData = new HashMap<String, String>();        userData.put(Name, sharedPreferences.getString(Name, null));        userData.put(Email, sharedPreferences.getString(Email, null));        userData.put(Phone, sharedPreferences.getString(Phone, null));        userData.put(DOB, sharedPreferences.getString(DOB, null));        userData.put(Password, sharedPreferences.getString(Password, null));        return userData;    }    public boolean chkLogin() {        if (sharedPreferences.getBoolean(isLoggedIn, false)) {            return true;        } else return false;    }    public void endLoginSession() {        editor.clear();        editor.commit();    }    /*----------------------REMEMBER ME------------------------*/    public void createRememberSession(String phone, String password) {        editor.putBoolean(isRemember, true);        editor.putString(rememberPhone, phone);        editor.putString(rememberPassword, password);        editor.commit();    }    public HashMap<String, String> getRememberSessionInfo() {        HashMap<String, String> userData = new HashMap<String, String>();        userData.put(rememberPhone, sharedPreferences.getString(rememberPhone, null));        userData.put(rememberPassword, sharedPreferences.getString(rememberPassword, null));        return userData;    }    public boolean chkRemember() {        if (sharedPreferences.getBoolean(isRemember, false)) {            return true;        } else return false;    }    /*----------------------FORGOT PASSWORD------------------------*/    public void createForgotSession(String phone) {        editor.putBoolean(isForgotPassword, true);        editor.putString(verifyPhone, phone);        editor.commit();    }    public HashMap<String, String> getForgotSessionInfo() {        HashMap<String, String> userData = new HashMap<String, String>();        userData.put(verifyPhone, sharedPreferences.getString(verifyPhone, null));        return userData;    }    public boolean chkForgot() {        if (sharedPreferences.getBoolean(isForgotPassword, false)) {            return true;        } else return false;    }}